 $agents=[];foreach([1,2]as $i=>$level){$id=Directory::saveAgent($t,['name'=>$prefix.'代理'.$i,'account'=>$prefix.'a'.$i,'password'=>'GeoQa2026!','level'=>$level,'parent_id'=>$level===2?$agents[0]:0]);$agents[]=$id;$r=gh('/tenantapi/login/account',['account'=>$prefix.'a'.$i,'password'=>'GeoQa2026!','terminal'=>1,'tenant_id'=>$t]);ghcheck($r['code']===1,'agent login '.$i);$agentTokens[]=$r['data']['token'];}
